{
  "requirement_definitions": [
    {
      "id": "R6.4.2(1)",
      "title": "visual alarm signal",
      "text": "If a visual indicator is necessary for the clinician to identify the equipment or part of the equipment that requires clinician response or awareness, at least one visual alarm signal shall be provided that:\n1. indicates the priority of the highest priority alarm condition; and\n2. can be perceived correctly at a distance of 4 m from the PCA pump."
    },
    {
      "id": "R6.4.2(2)",
      "title": "alarm indicator appearance",
      "text": "The alarm indicator appearance shall comply with color, ﬂashing frequency, and duty cycle given in Table 5."
    },
    {
      "id": "R6.4.2(3)",
      "title": "see alarm signal",
      "text": "At least one visual alarm signal shall be provided that identiﬁes the speciﬁc alarm condition and its priority. This signal shall be perceived correctly (be legible) at a distance of 1 m from the equipment or part of the equipment or from the clinician’s position."
    },
    {
      "id": "R6.4.2(4)",
      "title": "alarm symbols",
      "text": "Visual alarms shall display alarm symbols from Table D.201 Graphical symbols for ALARM SYSTEMS of standard IEC 60601-1-8."
    },
    {
      "id": "R6.4.3(1)",
      "title": "audible alarms signals",
      "text": "Alarms shall cause audible alarms signals that meet the requirements of Tables 203 and 204 of standard IEC 60601-1-8 for alarm pulses, bursts, and harmonics."
    },
    {
      "id": "R6.4.3(2)",
      "title": "auditory volume",
      "text": "The auditory volume of audible alarms signals shall conform to Section 201.3.3.2 Volume of auditory ALARM SIGNALS and INFORMATION SIGNALS of standard IEC 60601-1-8."
    },
    {
      "id": "R6.4.3(3)",
      "title": "alarm melody",
      "text": "The alarm melody of audible alarms signals shall conform to Table AAA.1 of standard IEC 60601-1-8 for drug or ﬂuid delivery. “C d g” shall be used for medium priority alarms; “C d g - C d” shall be used for high priority alarms; “e c” shall be used for warnings and low priority alarms."
    },
    {
      "id": "R6.4.3(4)",
      "title": "Harmonic components",
      "text": "Each tone in the alarm melody shall be composed of a minimum of 4 harmonic components in the range 300 Hz to 4000 Hz comprising an inverted 9th jazz chord."
    },
    {
      "id": "R6.4.3(5)",
      "title": "Alarm pause duration",
      "text": "Temporarily paused alarms shall reactivate alarm pause duration ∆ ap = 10 minutes after inactivation."
    },
    {
      "id": "R6.4.4(1)",
      "title": "Alarm occurrence order",
      "text": "Alarms shall be issued in order of occurrence."
    },
    {
      "id": "R6.4.4(2)",
      "title": "Alarm reactivation upon ICE disconnection",
      "text": "If alarms are inactivated or paused through the ICE supervisor user interface, they shall be reactivated upon loss of connection to ICE."
    },
    {
      "id": "R6.5(1)",
      "title": "Control panel display",
      "text": "The control panel must display currently-programmed patient data and physician’s prescription."
    }
  ],
  "allocation_entries": []
}
